import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_naive_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_naive_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int inC, int inD, int inH, int inW,
    int outC, int outD, int outH, int outW,
    int kD, int kH, int kW,
    int padD, int padH, int padW,
    int strideD, int strideH, int strideW,
    int dilationD, int dilationH, int dilationW
)
{
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_size = N * outC * outD * outH * outW;
    if (index >= total_size) return;

    // Decode the linear index into (n, oc, od, oh, ow)
    int tmp = index;
    int ow = tmp % outW;
    tmp /= outW;
    int oh = tmp % outH;
    tmp /= outH;
    int od = tmp % outD;
    tmp /= outD;
    int oc = tmp % outC;
    tmp /= outC;
    int n = tmp;

    float val = 0.0f;

    // Naive convolution
    for (int ic = 0; ic < inC; ic++) {
        for (int kd = 0; kd < kD; kd++) {
            int in_d = od * strideD - padD + kd * dilationD;
            if (in_d < 0 || in_d >= inD) continue;
            for (int kh = 0; kh < kH; kh++) {
                int in_h = oh * strideH - padH + kh * dilationH;
                if (in_h < 0 || in_h >= inH) continue;
                for (int kw_ = 0; kw_ < kW; kw_++) {
                    int in_w = ow * strideW - padW + kw_ * dilationW;
                    if (in_w < 0 || in_w >= inW) continue;

                    float input_val = input[(((n * inC + ic) * inD + in_d) * inH + in_h) * inW + in_w];
                    float weight_val = weight[(((oc * inC + ic) * kD + kd) * kH + kh) * kW + kw_];
                    val += input_val * weight_val;
                }
            }
        }
    }

    // Add bias if not null
    if (bias != nullptr) {
        val += bias[oc];
    }

    output[index] = val;
}

torch::Tensor conv3d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor output,
    int kD, int kH, int kW,
    int padD, int padH, int padW,
    int strideD, int strideH, int strideW,
    int dilationD, int dilationH, int dilationW
) {
    int N = input.size(0);
    int outC = weight.size(0);
    int total_size = N * outC * output.size(2) * output.size(3) * output.size(4);

    int threads = 256;
    int blocks = (total_size + threads - 1) / threads;

    conv3d_naive_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        (bias.defined() && bias.numel() > 0) ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        N,
        input.size(1),
        input.size(2),
        input.size(3),
        input.size(4),
        outC,
        output.size(2),
        output.size(3),
        output.size(4),
        kD, kH, kW,
        padD, padH, padW,
        strideD, strideH, strideW,
        dilationD, dilationH, dilationW
    );

    return output;
}
"""

conv3d_naive_cpp_source = r"""
torch::Tensor conv3d_naive_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor output,
    int kD, int kH, int kW,
    int padD, int padH, int padW,
    int strideD, int strideH, int strideW,
    int dilationD, int dilationH, int dilationW
);
"""

conv3d_naive_module = load_inline(
    name="conv3d_naive_module",
    cpp_sources=conv3d_naive_cpp_source,
    cuda_sources=conv3d_naive_source,
    functions=["conv3d_naive_cuda"],
    verbose=False,
)


def _triple(x):
    if isinstance(x, int):
        return (x, x, x)
    return x


class ModelNew(nn.Module):
    """
    Optimized 3D Convolution model with a custom CUDA kernel.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super(ModelNew, self).__init__()
        # Store parameters
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = _triple(kernel_size)
        self.stride = _triple(stride)
        self.padding = _triple(padding)
        self.dilation = _triple(dilation)
        self.groups = groups  # not used in the naive kernel
        # Create the weight parameter
        kD, kH, kW = self.kernel_size
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kD, kH, kW)
        )
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Extract shapes
        N, _, inD, inH, inW = x.shape
        kD, kH, kW = self.kernel_size
        sD, sH, sW = self.stride
        pD, pH, pW = self.padding
        dD, dH, dW = self.dilation

        # Compute output dimensions (same logic as PyTorch)
        outD = (inD + 2 * pD - dD * (kD - 1) - 1) // sD + 1
        outH = (inH + 2 * pH - dH * (kH - 1) - 1) // sH + 1
        outW = (inW + 2 * pW - dW * (kW - 1) - 1) // sW + 1

        # Create output tensor
        out = torch.empty(
            (N, self.out_channels, outD, outH, outW),
            device=x.device,
            dtype=x.dtype
        )

        # Call the naive CUDA kernel
        out = conv3d_naive_module.conv3d_naive_cuda(
            x,
            self.weight,
            self.bias if self.bias is not None else torch.tensor([]).to(x.device),
            out,
            kD, kH, kW,
            pD, pH, pW,
            sD, sH, sW,
            dD, dH, dW
        )
        return out
